44	function coercePlayerPrefs(raw: unknown): Partial<PlayerPrefs> {
45	  if (!raw || typeof raw !== "object") return {};
46	  const r = raw as Record<string, unknown>;
47	  const out: { -readonly [K in keyof PlayerPrefs]?: PlayerPrefs[K] } = {};
48	  if (typeof r.speed === "number") out.speed = r.speed;
49	  if (typeof r.volume === "number") out.volume = r.volume;
50	  if (typeof r.collapsed === "boolean") out.collapsed = r.collapsed;
51	  return out;
