54	function migrateLegacyPlayerPrefs(): void {
55	  if (localStorage.getItem(PLAYER_PREFS_KEY) !== null) return;
56	  const legacySpeed = localStorage.getItem("readaloud-playback-speed");
57	  const legacyVolume = localStorage.getItem("readaloud-volume");
58	  const legacyCollapsed = localStorage.getItem("readaloud-player-collapsed");
59	  if (legacySpeed === null && legacyVolume === null && legacyCollapsed === null)
60	    return;
61	  const migrated: PlayerPrefs = {
62	    speed:
63	      legacySpeed !== null
64	        ? Number.parseFloat(legacySpeed)
65	        : PLAYER_PREFS_DEFAULTS.speed,
66	    volume:
67	      legacyVolume !== null
68	        ? Number.parseFloat(legacyVolume)
69	        : PLAYER_PREFS_DEFAULTS.volume,
