82	function findActiveWord(
83	  timings: ReadonlyArray<WordTiming>,
84	  ms: number,
85	): number {
86	  let idx = -1;
87	  let lo = 0;
88	  let hi = timings.length - 1;
89	  while (lo <= hi) {
90	    const mid = (lo + hi) >>> 1;
91	    const t = timings[mid];
92	    if (!t) break;
93	    if (ms >= t.startMs && ms < t.endMs) {
94	      idx = mid;
95	      break;
96	    } else if (ms < t.startMs) {
97	      hi = mid - 1;
98	    } else {
99	      idx = mid;
100	      lo = mid + 1;
101	    }
102	  }
103	  if (idx >= 0 && idx < timings.length - 1) {
104	    const next = timings[idx + 1];
105	    if (next && ms >= next.startMs) idx += 1;
106	  }
107	  return idx;
108	}
109	
110	function formatTime(secs: number): string {
111	  if (!Number.isFinite(secs) || secs < 0) return "0:00";
112	  const m = Math.floor(secs / 60);
113	  const s = Math.floor(secs % 60);
114	  return `${m}:${s < 10 ? "0" : ""}${s}`;
115	}
116	
117	export const AudioPlayerHook = defineHook<HTMLDivElement, AudioPlayerDataset>(
118	  (ctx) => {
119	    const audio = requireElement(DOM_IDS.AUDIO_ELEMENT, HTMLAudioElement);
120	    const playPauseBtn = requireElement(DOM_IDS.PLAY_PAUSE_BTN, HTMLElement);
121	    const timeDisplay = findElement(DOM_IDS.TIME_DISPLAY, HTMLElement);
122	    const textContainer = findElement(DOM_IDS.CHAPTER_TEXT, HTMLElement);
123	    const resyncBtn = findElement(DOM_IDS.RESYNC_BTN, HTMLElement);
124	    const speedBadge = findElement(DOM_IDS.SPEED_BADGE, HTMLElement);
125	
126	    if (!audio || !playPauseBtn) return;
127	
128	    let timings: ReadonlyArray<WordTiming> = [];
129	    let currentWordIndex = -1;
130	    let lastReportedMs = -1;
131	    let rafId: number | undefined;
132	    let wordMenuCleanup: (() => void) | undefined;
133	    let intersectionObserver: IntersectionObserver | undefined;
134	
135	    const applyAudioPrefs = (): void => {
136	      const p = playerPrefs.get();
137	      audio.playbackRate = p.speed;
138	      audio.volume = p.volume;
139	      updateSpeedBadge(p.speed);
140	    };
141	
142	    const updateTimeDisplay = (): void => {
143	      if (!timeDisplay) return;
144	      timeDisplay.textContent = `${formatTime(audio.currentTime)} / ${formatTime(audio.duration)}`;
145	    };
146	
147	    const updateSpeedBadge = (speed: number): void => {
148	      if (!speedBadge) return;
149	      speedBadge.textContent = speed === 1 ? "1x" : `${speed}x`;
150	    };
151	
152	    const setSpeed = (speed: number): void => {
153	      playerPrefs.set({ speed });
154	      audio.playbackRate = speed;
155	      updateSpeedBadge(speed);
156	    };
157	
158	    const cycleSpeed = (direction: "up" | "down"): void => {
159	      const closest = SPEEDS.reduce((best, s) =>
160	        Math.abs(s - audio.playbackRate) < Math.abs(best - audio.playbackRate)
161	          ? s
162	          : best,
163	      );
164	      setSpeed(cycleOption(SPEEDS, closest, direction));
165	    };
166	
167	    const togglePlayback = (): void => {
168	      if (audio.paused) audio.play();
169	      else audio.pause();
170	    };
171	
172	    const seekToWordIndex = (idx: number): void => {
173	      const t = timings[idx];
174	      if (!t) return;
175	      audio.currentTime = t.startMs / 1000;
176	      if (audio.paused) audio.play();
177	    };
178	
179	    // Word highlighting with auto-scroll
180	    const highlightWord = (ms: number): void => {
181	      if (!textContainer || timings.length === 0) return;
182	      const idx = findActiveWord(timings, ms);
183	      if (idx === currentWordIndex) return;
184	
185	      if (currentWordIndex >= 0) {
186	        const old = textContainer.querySelector<HTMLElement>(
187	          wordSelector(currentWordIndex),
188	        );
189	        old?.classList.remove("word-active");
190	        old?.classList.add("word-spoken");
191	      }
192	
193	      if (idx >= 0) {
194	        const next = textContainer.querySelector<HTMLElement>(
195	          wordSelector(idx),
196	        );
197	        if (next) {
198	          next.classList.add("word-active");
199	          next.classList.remove("word-spoken");
200	
201	          if (!scrollFollow.get().autoScrollPaused) {
202	            scrollFollow.beginAutoScroll(AUTO_SCROLL_GRACE_MS);
203	            next.scrollIntoView({ behavior: "smooth", block: "center" });
204	            if (intersectionObserver) {
205	              intersectionObserver.disconnect();
206	              intersectionObserver.observe(next);
207	            }
208	          }
209	        }
210	      }
211	
212	      if (idx > currentWordIndex) {
213	        for (let i = Math.max(0, currentWordIndex); i < idx; i++) {
214	          const el = textContainer.querySelector<HTMLElement>(wordSelector(i));
215	          if (el) {
216	            el.classList.remove("word-active");
217	            el.classList.add("word-spoken");
218	          }
219	        }
220	      } else if (idx >= 0 && idx < currentWordIndex) {
221	        for (let i = idx + 1; i <= currentWordIndex; i++) {
222	          const el = textContainer.querySelector<HTMLElement>(wordSelector(i));
223	          if (el) el.classList.remove("word-spoken", "word-active");
224	        }
225	      }
226	
227	      currentWordIndex = idx;
228	    };
229	
230	    const startHighlightLoop = (): void => {
231	      const tick = (): void => {
232	        if (!audio.paused) {
233	          highlightWord(audio.currentTime * 1000);
234	          rafId = requestAnimationFrame(tick);
235	        }
236	      };
237	      rafId = requestAnimationFrame(tick);
238	    };
239	
240	    const stopHighlightLoop = (): void => {
241	      if (rafId !== undefined) {
242	        cancelAnimationFrame(rafId);
243	        rafId = undefined;
244	      }
245	    };
246	
247	    // Initial setup
248	    if (playerPrefs.get().collapsed) ctx.el.classList.add("collapsed");
249	
250	    const volSlider = ctx.el.querySelector<HTMLInputElement>(
251	      "[data-volume-slider]",
252	    );
253	    if (volSlider) volSlider.value = String(playerPrefs.get().volume);
254	    updateSpeedBadge(playerPrefs.get().speed);
255	
256	    // The <audio> element has phx-update="ignore" so it's preserved across
257	    // same-LV navigation (auto-next chapter). Reassigning .src alone doesn't
258	    // reliably refetch on iOS Safari — call load() explicitly to invoke the
259	    // resource selection algorithm and reset the element's media state.
260	    audio.src = ctx.dataset.audioUrl;
261	    audio.load();
262	    applyAudioPrefs();
263	
264	    ctx.on(audio, "loadedmetadata", () => {
265	      applyAudioPrefs();
266	      updateTimeDisplay();
267	    });
268	    ctx.on(audio, "durationchange", updateTimeDisplay);
269	
270	    // Word timings
271	    fetch(ctx.dataset.timingsUrl)
272	      .then((r) => r.json())
273	      .then((data: unknown) => {
274	        timings = parseWordTimings(data);
275	        if (textContainer) wordMenuCleanup = attachWordMenu(textContainer);
276	      })
277	      .catch((err: unknown) =>
278	        console.error("AudioPlayer: failed to load timings", err),
279	      );
280	
281	    // Restore initial position
282	    const initialMs = Number.parseInt(ctx.dataset.initialPosition ?? "0", 10);
283	    if (initialMs > 0) {
284	      ctx.on(
285	        audio,
286	        "loadedmetadata",
287	        () => {
288	          audio.currentTime = initialMs / 1000;
289	        },
290	        { once: true },
291	      );
292	    }
293	
294	    // Auto-play handoff: if the previous chapter ended with auto-next-chapter
295	    // enabled, the ended handler stashed a flag in sessionStorage. Consume it
296	    // and start playback once metadata is loaded.
297	    if (sessionStorage.getItem(AUTO_NEXT_HANDSHAKE_KEY) === "1") {
298	      sessionStorage.removeItem(AUTO_NEXT_HANDSHAKE_KEY);
299	      ctx.on(
300	        audio,
301	        "loadedmetadata",
302	        () => {
303	          audio.play().catch((err: unknown) => {
304	            console.warn("AudioPlayer: auto-play blocked by browser", err);
305	          });
306	        },
307	        { once: true },
308	      );
309	    }
310	
311	    // Controls
312	    ctx.on(playPauseBtn, "click", togglePlayback);
313	
314	    const skipBack = ctx.el.querySelector<HTMLElement>("[data-skip-back]");
315	    const skipFwd = ctx.el.querySelector<HTMLElement>("[data-skip-forward]");
316	    if (skipBack) {
317	      ctx.on(skipBack, "click", () => {
318	        audio.currentTime = Math.max(0, audio.currentTime - SKIP_SECONDS);
319	      });
320	    }
321	    if (skipFwd) {
322	      ctx.on(skipFwd, "click", () => {
323	        const max = Number.isFinite(audio.duration)
324	          ? audio.duration
325	          : Number.POSITIVE_INFINITY;
326	        audio.currentTime = Math.min(max, audio.currentTime + SKIP_SECONDS);
327	      });
328	    }
329	
330	    const collapseToggle = ctx.el.querySelector<HTMLElement>(
331	      "[data-collapse-toggle]",
332	    );
333	    if (collapseToggle) {
334	      ctx.on(collapseToggle, "click", () => {
335	        const isCollapsed = ctx.el.classList.toggle("collapsed");
336	        playerPrefs.set({ collapsed: isCollapsed });
337	      });
338	    }
339	
340	    if (volSlider) {
341	      ctx.on(volSlider, "input", () => {
342	        const vol = Number.parseFloat(volSlider.value);
343	        audio.volume = vol;
344	        playerPrefs.set({ volume: vol });
345	      });
346	    }
347	
348	    // Scrubbers (main + mini)
349	    const scrubMain = ctx.el.querySelector<HTMLElement>("[data-scrubber]");
350	    const scrubMini = ctx.el.querySelector<HTMLElement>("[data-scrubber-mini]");
351	    const seekToFraction = (f: number): void => {
352	      if (Number.isFinite(audio.duration))
353	        audio.currentTime = f * audio.duration;
354	    };
355	    for (const sc of [scrubMain, scrubMini]) {
356	      if (!sc) continue;
357	      const dispose = attachScrubber<number>({
358	        el: sc,
359	        indexAt: (clientX) => fractionAt(sc, clientX),
360	        preview: () => {},
361	        commit: seekToFraction,
362	      });
363	      ctx.onDestroy(dispose);
364	    }
365	
366	    // Time updates: progress bars + time display + position report
367	    ctx.on(audio, "timeupdate", () => {
368	      if (!audio.duration) return;
369	      const pct = (audio.currentTime / audio.duration) * 100;
370	      const fill = ctx.el.querySelector<HTMLElement>("[data-progress-fill]");
371	      if (fill) fill.style.width = `${pct}%`;
372	      const fillMini = ctx.el.querySelector<HTMLElement>(
373	        "[data-progress-fill-mini]",
374	      );
375	      if (fillMini) fillMini.style.width = `${pct}%`;
376	      updateTimeDisplay();
377	
378	      const nowMs = Math.round(audio.currentTime * 1000);
379	      if (
380	        lastReportedMs < 0 ||
381	        Math.abs(nowMs - lastReportedMs) >= POSITION_REPORT_INTERVAL_MS
382	      ) {
383	        lastReportedMs = nowMs;
384	        ctx.pushEvent("audio_position", { position_ms: nowMs });
385	      }
386	    });
387	
388	    // Play/pause state — drives scrollFollow + button icon + position report
389	    ctx.on(audio, "play", () => {
390	      playPauseBtn.innerHTML = "&#10074;&#10074;";
391	      scrollFollow.setPlaying(true);
392	      startHighlightLoop();
393	    });
394	    ctx.on(audio, "pause", () => {
395	      playPauseBtn.innerHTML = "&#9654;";
396	      scrollFollow.setPlaying(false);
397	      stopHighlightLoop();
398	      ctx.pushEvent("audio_position", {
399	        position_ms: Math.round(audio.currentTime * 1000),
400	      });
401	    });
402	    ctx.on(audio, "ended", () => {
403	      stopHighlightLoop();
404	      if (readerSettings.get().autoNextChapter) {
405	        sessionStorage.setItem(AUTO_NEXT_HANDSHAKE_KEY, "1");
406	        ctx.pushEvent("next_chapter");
407	      }
408	    });
409	
410	    // Re-sync UX
411	    if (resyncBtn) {
412	      ctx.on(resyncBtn, "click", () => {
413	        scrollFollow.resume();
414	        if (currentWordIndex >= 0 && textContainer) {
415	          const el = textContainer.querySelector<HTMLElement>(
416	            wordSelector(currentWordIndex),
417	          );
418	          el?.scrollIntoView({ behavior: "smooth", block: "center" });
419	        }
420	      });
421	    }
422	
423	    if (textContainer && "IntersectionObserver" in window) {
424	      intersectionObserver = new IntersectionObserver(
425	        (entries) => {
426	          for (const entry of entries) {
427	            if (entry.isIntersecting && scrollFollow.get().autoScrollPaused) {
428	              scrollFollow.resume();
429	            }
430	          }
431	        },
432	        { threshold: 0.5 },
433	      );
434	      ctx.onDestroy(() => intersectionObserver?.disconnect());
435	    }
436	
437	    const unsubScroll = scrollFollow.subscribe((s) => {
438	      if (!resyncBtn) return;
439	      if (s.autoScrollPaused) resyncBtn.classList.remove("hidden");
440	      else resyncBtn.classList.add("hidden");
441	    });
442	    ctx.onDestroy(unsubScroll);
443	
444	    // Word menu actions
445	    ctx.on(window, "word-action", (detail) => {
446	      if (detail.kind === "play") seekToWordIndex(detail.index);
447	    });
448	
449	    // Speed badge cycle
450	    if (speedBadge) ctx.on(speedBadge, "click", () => cycleSpeed("up"));
451	
452	    // Keyboard-shortcut events
453	    ctx.on(window, "audio:toggle-playback", togglePlayback);
454	    ctx.on(window, "audio:toggle-mute", () => {
455	      audio.muted = !audio.muted;
456	    });
457	    ctx.on(window, "audio:change-speed", ({ direction }) =>
458	      cycleSpeed(direction),
459	    );
460	
461	    // Final cleanup not covered by ctx.on
462	    ctx.onDestroy(() => {
463	      stopHighlightLoop();
464	      audio.pause();
465	      wordMenuCleanup?.();
466	    });
467	  },
468	);
