146			// it for this test.
147			await page.evaluate(() => {
148				const cur = (() => {
149					try {
150						return JSON.parse(
151							localStorage.getItem("readaloud-reader-settings") || "{}",
152						);
153					} catch {
154						return {};
155					}
156				})();
157				cur.autoNextChapter = true;
158				localStorage.setItem("readaloud-reader-settings", JSON.stringify(cur));
159			});
160	
161			// Trigger the `ended` event on the audio element. The hook listens
162			// for this and is supposed to swap src to the next chapter and push
163			// next_chapter to the server (push_patch).
164			await page.evaluate(() => {
165				const a = document.getElementById("audio-element");
166				if (a) a.dispatchEvent(new Event("ended"));
167			});
168	
169			// Wait for the JS swap + LV push_patch round-trip.
170			await sleep(1500);
171	
172			const after = await page.evaluate(() => {
173				const audio = document.getElementById("audio-element");
174				return {
175					url: window.location.pathname + window.location.search,
176					audioSrc: audio?.src ?? null,
177					audioNodeMarker: audio ? audio.dataset.testId : null,
178				};
179			});
180	
181			// Same DOM node — proves push_patch (not push_navigate).
182			assert.strictEqual(
183				after.audioNodeMarker,
184				"same-node-marker",
185				"audio element must be the SAME node — push_navigate would replace it",
186			);
187	
188			// audio.src now points at the next chapter.
189			assert.strictEqual(
190				after.audioSrc,
191				before.nextAudioUrl && new URL(before.nextAudioUrl, BASE_URL).toString(),
192				`audio.src should be next chapter URL after ended, got ${after.audioSrc}`,
193			);
194	
195			// URL got patched to the next chapter.
196			assert.ok(
197				after.url.includes(`/read/${before.nextChapterId}`),
198				`URL should be patched to /read/${before.nextChapterId}, got ${after.url}`,
199			);
200		});
201	});
